const dayKey=(d=new Date())=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
let state;try{state=JSON.parse(localStorage.getItem('wordly-v1'))}catch{}state=Object.assign({records:{},activity:{},goal:10,xp:0,weekly:{},testResults:[]},state||{});
let storageOkay=true;function save(){try{localStorage.setItem('wordly-v1',JSON.stringify(state))}catch{storageOkay=false;toast('Browser storage is unavailable. This session cannot be saved.')}}
const now=()=>Date.now(),rec=id=>state.records[id],due=()=>words.filter(w=>rec(w.id)&&rec(w.id).due<=now()),learned=()=>Object.keys(state.records).length,mastered=()=>Object.values(state.records).filter(r=>r.interval>=7).length,today=()=>state.activity[dayKey()]||{ids:[],answers:0,correct:0},weekKeys=()=>Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-6+i);return dayKey(d)}),weekXP=()=>weekKeys().reduce((n,k)=>n+(state.weekly[k]||0),0);
function streak(){let n=0,d=new Date();if(!state.activity[dayKey(d)])d.setDate(d.getDate()-1);while(state.activity[dayKey(d)]){n++;d.setDate(d.getDate()-1)}return n}
function record(w,rating){let r=rec(w.id)||{interval:0,ease:2.3,reviews:0,lapses:0};if(rating==='unknown'){r.interval=0;r.due=now()+60000;r.lapses++;r.ease=Math.max(1.3,r.ease-.2)}else if(rating==='difficult'){r.interval=Math.max(1,Math.round(r.interval*1.2));r.due=now()+r.interval*86400000;r.ease=Math.max(1.3,r.ease-.1)}else{r.interval=r.interval===0?1:r.interval===1?3:Math.round(r.interval*r.ease);r.due=now()+r.interval*86400000;r.ease=Math.min(2.8,r.ease+.05)}r.reviews++;r.last=now();r.status=rating;state.records[w.id]=r;const key=dayKey();let a=state.activity[key]||(state.activity[key]={ids:[],answers:0,correct:0});const first=!a.ids.includes(w.id);if(first)a.ids.push(w.id);a.answers++;if(rating==='known')a.correct++;let xp=first?(rating==='known'?15:5):0;state.xp+=xp;state.weekly[key]=(state.weekly[key]||0)+xp;save()}
function speak(id){if(!('speechSynthesis'in window)){toast('Your browser does not support audio pronunciation.');return}speechSynthesis.cancel();const s=new SpeechSynthesisUtterance(words[id].en);s.lang='en-GB';s.rate=.82;speechSynthesis.speak(s)}
let toastTimer;function toast(s){const el=document.getElementById('toast');el.textContent=s;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3500)}
let page=location.hash.slice(1)||'dashboard',session=null,filter=-1,search='',board='weekly';
const nav=[['dashboard','home','Overview'],['units','book','Vocabulary'],['review','repeat','Daily review'],['flashcards','cards','Flashcards'],['tests','test','Knowledge tests'],['statistics','chart','My progress'],['leaderboard','trophy','Leaderboard']];
function go(p){session=null;location.hash=p;if(page===p)render()}
window.addEventListener('hashchange',()=>{page=location.hash.slice(1)||'dashboard';if(session&&((session.kind==='test'&&page!=='tests')||(session.kind!=='test'&&!['review','flashcards'].includes(page))))session=null;if(!nav.some(n=>n[0]===page)&&page!=='settings'&&!/^unit-(?:[1-9]|[1-9][0-9]|100)$/.test(page))page='dashboard';render();window.scrollTo(0,0)});
function render(){const title=nav.find(n=>n[0]===page)?.[2]||(page.startsWith('unit-')?'Textbook unit':'Study preferences');document.getElementById('app').innerHTML=`<div class="shell"><aside class="sidebar"><a href="#dashboard" class="brand"><span class="brandmark">w</span>WORDLY<span style="font-size:7px;letter-spacing:0;align-self:start;color:#7087a9">®</span></a><div class="workspace-label">YOUR LEARNING SPACE</div><nav class="nav">${nav.map(([p,i,n])=>`<a href="#${p}" class="${page===p?'active':''}" ${page===p?'aria-current="page"':''}>${icon(i)}${n}${p==='review'&&due().length?`<small>${due().length}</small>`:''}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="level-card"><div class="eyebrow">YOUR LEARNING JOURNEY</div><strong>Level ${Math.floor(state.xp/500)+1} · ${state.xp<500?'Building foundations':'Growing vocabulary'}</strong><div class="bar"><i style="width:${state.xp%500/5}%"></i></div><small>${state.xp%500} / 500 XP to next level</small></div><a href="#settings" class="profile"><span class="avatar">YS</span><span><strong>Your workspace</strong><small>Independent learner</small></span><span style="margin-left:auto">${icon('settings')}</span></a></div></aside><main class="main"><header class="topbar"><div class="crumb">Workspace <span>/</span> <strong>${title}</strong></div><div class="top-actions"><span class="streak">${icon('flame')}${streak()} day streak</span><span class="avatar">YS</span></div></header><div class="content">${page.startsWith('unit-')?bookLesson():page==='dashboard'?dashboard():page==='units'?vocabulary():page==='review'||page==='flashcards'?study():page==='tests'?tests():page==='statistics'?statistics():page==='leaderboard'?leaderboard():settings()}<footer class="footer"><span>${icon('leaf')} A little practice. Lasting knowledge.</span><span>WORDLY · Your personal vocabulary workspace</span></footer></div></main></div>`;bind();}
function heading(eyebrow,title,sub){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${sub}</p></div><div class="date">${icon('calendar')}${new Date().toLocaleDateString('en-GB',{day:'numeric',month:'long',year:'numeric'})}</div></div>`}
function stat(label,value,note,i){return `<div class="stat"><div class="stat-top">${label}<span class="icon-box">${icon(i)}</span></div><strong>${value}</strong><small>${note}</small></div>`}
function table(list){return `<table class="word-table"><thead><tr><th>English word</th><th>Uzbek translation</th><th>Status</th><th><span class="muted">Audio</span></th></tr></thead><tbody>${list.map(w=>`<tr><td><strong>${esc(w.en)}</strong><small>${w.pos}</small></td><td>${esc(w.uz)}</td><td><span class="status ${rec(w.id)?.interval>=7?'':'learning'}">${rec(w.id)?rec(w.id).interval>=7?'Retained':rec(w.id).status==='unknown'?'Needs review':'Learning':'New word'}</span></td><td><button class="sound" data-speak="${w.id}" aria-label="Pronounce ${w.en}">${icon('sound')}</button></td></tr>`).join('')}</tbody></table>`}
function activity(){let keys=weekKeys(),counts=keys.map(k=>(state.activity[k]?.ids||[]).length),max=Math.max(10,...counts);return `<div class="card"><div class="card-head"><h2>Study activity</h2><span class="muted" style="font-size:9px">Last 7 days</span></div><div class="activity-top"><strong>${counts.reduce((a,b)=>a+b,0)}</strong><span>words practised</span></div><div class="chart">${keys.map((k,i)=>`<div class="chart-day ${i===6?'today':''}" title="${k}: ${counts[i]} words"><i style="height:${counts[i]/max*75}px"></i><span>${new Date(k+'T12:00:00').toLocaleDateString('en',{weekday:'narrow'})}</span></div>`).join('')}</div><p class="activity-foot"><span>${counts.filter(n=>n>0).length} active days</span> · Consistency builds confidence.</p></div>`}
function rankingPreview(){return `<div class="card"><div class="card-head"><h2>Your place to grow</h2>${icon('trophy')}</div><div class="tabs"><button data-board="weekly" class="${board==='weekly'?'active':''}">This week</button><button data-board="global" class="${board==='global'?'active':''}">All time</button></div><div class="ranking"><span class="rank">—</span><span class="avatar">YS</span><span class="person"><strong>You</strong><small>Independent learner</small></span><span class="xp">${board==='weekly'?weekXP():state.xp} XP</span></div><div class="leader-note">Your progress is personal. Shared rankings will appear when a community is connected.</div><a class="text-link" style="margin-top:15px" href="#leaderboard">View leaderboard ${icon('arrow')}</a></div>`}
function dashboard(){const count=today().ids.length,progress=Math.min(100,count/state.goal*100),u=words.find(w=>!rec(w.id))?.unit??0,ul=words.filter(w=>w.unit===u),uc=ul.filter(w=>rec(w.id)).length,recent=words.filter(w=>rec(w.id)).sort((a,b)=>rec(b.id).last-rec(a.id).last).slice(0,4);return `${heading('MAKE EVERY WORD STAY','Small steps. Stronger English.','A focused space to learn, remember, and move forward.')}<div class="dashboard-grid"><div class="left-col"><section class="hero"><div><div class="eyebrow">TODAY’S LEARNING GOAL</div><h2>${count>=state.goal?'A good day for your English.':'Build a vocabulary that stays with you.'}</h2><p>${count>=state.goal?'Daily goal complete. Keep your momentum tomorrow.':`Just ${Math.max(0,state.goal-count)} more words. A little progress goes a long way.`}</p><button class="btn" data-start="new">Continue learning ${icon('arrow')}</button></div><div class="hero-ring" style="--progress:${progress}%"><div><strong>${count}<span> / ${state.goal}</span></strong><small>words practised today</small></div></div></section><div class="stats">${stat('Words studied',learned(),`of ${words.length} in your library`,'book')}${stat('Words retained',mastered(),'Scheduled at least 7 days out','target')}${stat('Study streak',`${streak()} <span style="font-size:13px;font-weight:500;color:#94a0b1">days</span>`,streak()?'Keep the rhythm going':'Your next chapter starts today','flame')}</div><section class="card"><div class="card-head"><h2>Pick up where you left off</h2><a href="#units" class="text-link">All units ${icon('arrow')}</a></div><div class="unit-content"><div class="unit-art">${icon('book')}</div><div class="unit-info"><span class="tag">UNIT ${String(u+1).padStart(2,'0')} · A2–B1</span><h3>${units[u]}</h3><p>${ul.length} useful words · Everyday English</p></div><button class="btn secondary" data-open-unit="${u+1}">Open unit ${icon('arrow')}</button></div><div class="unit-progress"><div class="bar"><i style="width:${uc/ul.length*100}%"></i></div><span>${uc} of ${ul.length} studied</span></div></section><section class="card"><div class="card-head"><h2>${recent.length?'Recently studied vocabulary':'Your first words start here'}</h2><a href="#units" class="text-link">View vocabulary ${icon('arrow')}</a></div>${table(recent.length?recent:words.slice(0,4))}</section></div><aside class="right-col"><section class="card review-card"><div class="eyebrow">${icon('repeat')} DAILY REVIEW</div><h2>${due().length?`${due().length} words ready for review`:'Make room for remembering.'}</h2><p>${due().length?'A quick refresh today makes these words easier to recall tomorrow.':'Study your first words today. We’ll bring them back when it’s time to review.'}</p><div class="review-meta">${icon('clock')}${due().length?`About ${Math.max(1,Math.ceil(due().length*.5))} minutes`:'Personalised spaced repetition'}</div><button class="btn" data-start="${due().length?'review':'new'}">${due().length?'Start daily review':'Start your first session'} ${icon('arrow')}</button></section>${activity()}${rankingPreview()}</aside></div>`}
function vocabulary(){return bookCatalog()}
function start(kind,unit){let list=kind==='review'?due().sort((a,b)=>(rec(b.id).lapses-rec(a.id).lapses)||(rec(a.id).due-rec(b.id).due)):kind==='unit'?words.filter(w=>w.unit===unit):words.filter(w=>!rec(w.id)).slice(0,state.goal);if(kind==='new'&&!list.length)list=words.slice(0,state.goal);session={kind,list,index:0,flipped:false,mode:'flash',answer:'',checked:false,correct:false,done:0};page=kind==='review'?'review':'flashcards';if(location.hash!==`#${page}`)location.hash=page;else render()}
function study(){if(!session){const isReview=page==='review',n=due().length;return `${heading(isReview?'A LITTLE REFRESH':'FOCUSED PRACTICE',isReview?'Bring your words back to mind.':'Make a connection. Keep the word.',isReview?'Your review queue adapts to what you remember and what needs another look.':'Read, listen, recall. A simple routine for stronger vocabulary.')}<div class="study-wrap"><section class="card flashcard"><span class="icon-box">${icon(isReview?'repeat':'cards')}</span><h2 style="font-size:28px">${isReview?`${n} words due for review`:'Your next study session'}</h2><p>${isReview&&!n?'You’re up to date. New words return after one day; forgotten words return after one minute.':'Try to remember the meaning before revealing the answer. Rate each word honestly to personalise your next review.'}</p><button class="btn" data-start="${isReview&&n?'review':'new'}">${isReview&&n?'Begin daily review':'Learn vocabulary'} ${icon('arrow')}</button></section><p class="hint">Space to reveal · 1 unknown · 2 difficult · 3 known · ← previous<br>Your progress is saved in this browser.</p></div>`}const s=session,w=s.list[s.index];if(!w)return complete();return `${heading(s.kind==='review'?'DAILY REVIEW':'VOCABULARY PRACTICE','Give this word a moment.','Try to recall before you reveal. The effort is part of learning.')}<div class="study-wrap"><div class="session-progress"><span>Word ${s.index+1} of ${s.list.length}</span><div class="bar"><i style="width:${s.index/s.list.length*100}%"></i></div><span>${Math.round(s.index/s.list.length*100)}%</span></div><div class="mode-tabs"><button class="btn ${s.mode==='flash'?'':'secondary'}" data-mode="flash">Flashcard</button><button class="btn ${s.mode==='uz'?'':'secondary'}" data-mode="uz">English → Uzbek</button><button class="btn ${s.mode==='en'?'':'secondary'}" data-mode="en">Uzbek → English</button></div><section class="card flashcard"><span class="tag">${s.mode==='en'?'RECALL THE ENGLISH WORD':w.pos}</span><h2>${esc(s.mode==='en'?w.uz:w.en)}</h2>${s.mode!=='en'?`<div class="phonetic">${w.ipa}<button class="sound" data-speak="${w.id}" aria-label="Play pronunciation">${icon('sound')}</button></div>`:''}${s.mode==='flash'?s.flipped?`<div class="translation">${esc(w.uz)}</div><p>${esc(w.def)}<br><em>“${esc(w.example)}”</em></p>`:`<p>Can you remember the Uzbek meaning?</p><button class="btn secondary" id="reveal">Reveal translation ${icon('arrow')}</button>`:`<form id="recall-form" style="width:100%"><input id="answer" class="recall-input" aria-label="Your translation" autocomplete="off" placeholder="Type ${s.mode==='en'?'the English word':'the Uzbek translation'}…" value="${esc(s.answer)}" ${s.checked?'disabled':''}><br>${s.checked?'':`<button class="btn" type="submit">Check answer ${icon('arrow')}</button>`}</form>${s.checked?`<div class="feedback ${s.correct?'':'wrong'}">${s.correct?'Correct. Nicely recalled.':`Keep practising. The answer is <strong>${esc(s.mode==='en'?w.en:w.uz)}</strong>.`}<br>${esc(w.def)}<br><em>${esc(w.example)}</em></div><button class="btn" id="next-recall">Continue ${icon('arrow')}</button>`:''}`}</section>${s.mode==='flash'&&s.flipped?`<div class="study-controls"><button class="btn secondary" data-rate="unknown">1 · Unknown <small>1 min</small></button><button class="btn secondary" data-rate="difficult">2 · Difficult <small>1 day+</small></button><button class="btn" data-rate="known">3 · Known <small>${nextDays(w)} day${nextDays(w)>1?'s':''}</small></button></div>`:''}<p class="hint">${s.mode==='flash'?'Space to reveal · 1 unknown · 2 difficult · 3 known · ← previous':'Type your answer, then press Enter.'}</p></div>`}
function nextDays(w){const r=rec(w.id);return !r||r.interval===0?1:r.interval===1?3:Math.round(r.interval*r.ease)}
function advance(){session.index++;session.flipped=false;session.answer='';session.checked=false;render()}
function complete(){return `${heading('SESSION COMPLETE','That’s progress worth keeping.','Every honest attempt strengthens your next recall.')}<div class="study-wrap"><section class="card flashcard"><span class="icon-box">${icon('check')}</span><div class="big-number">${session.done}</div><h2 style="font-size:25px;margin-top:0">Words practised</h2><p>Your next reviews are scheduled. Difficult words return sooner, and words you know get more time.</p><div class="study-controls"><button class="btn" data-go="dashboard">Back to overview ${icon('arrow')}</button><button class="btn secondary" data-go="statistics">See my progress</button></div></section></div>`}
const norm=s=>s.toLowerCase().trim().replace(/[‘’ʻʼ`]/g,"'").replace(/[^\p{L}\p{N}' ]/gu,'').replace(/\s+/g,' ');
function checkRecall(){const s=session,w=s.list[s.index],value=document.getElementById('answer').value;if(!value.trim())return toast('Type an answer first.');s.answer=value;s.correct=norm(value)===norm(s.mode==='en'?w.en:w.uz);s.checked=true;record(w,s.correct?'known':'unknown');s.done++;render()}
function tests(){if(!session||session.kind!=='test')return `${heading('CHECK YOUR UNDERSTANDING','Go beyond recognition.','Test your vocabulary in five ways. Get a correction after every answer.')}<div class="section-grid">${[['choice','Multiple choice','Choose the correct meaning.'],['translation','Translation','Recall an English word from its Uzbek meaning.'],['blank','Fill in the blank','Find the missing word in a definition.'],['sentence','Sentence completion','Use a word in a real context.'],['listening','Listening comprehension','Listen, then type the word you hear.']].map(([m,t,d])=>`<section class="card unit-tile"><span class="icon-box">${icon(m==='listening'?'sound':'test')}</span><h2>${t}</h2><p>${d}<br>6 questions · Immediate feedback</p><button class="btn secondary" data-test="${m}">Start practice ${icon('arrow')}</button></section>`).join('')}</div>`;const s=session,w=s.list[s.index];if(!w)return `${heading('TEST COMPLETE','A clearer picture of your learning.','Use your corrections to guide your next study session.')}<section class="card flashcard study-wrap"><div class="big-number">${s.score} / ${s.list.length}</div><h2 style="font-size:24px">${s.score===s.list.length?'Well remembered.':'Keep building your recall.'}</h2><p>Your vocabulary review schedule has been updated with these results.</p><button class="btn" data-go="tests">Choose another test ${icon('arrow')}</button></section>`;let prompt=s.testMode==='choice'?w.en:s.testMode==='translation'?w.uz:s.testMode==='listening'?'Listen carefully':s.testMode==='sentence'?w.example.replace(new RegExp(w.en,'ig'),'_____'):`${w.def} · ${w.en[0]}${' _'.repeat(w.en.length-1)}`;return `${heading('KNOWLEDGE TEST','Put your vocabulary to work.','Take your time. Think about the meaning, not just the answer.')}<div class="study-wrap"><div class="session-progress"><span>Question ${s.index+1} / ${s.list.length}</span><div class="bar"><i style="width:${s.index/s.list.length*100}%"></i></div></div><section class="card flashcard"><span class="tag">${s.testMode.replaceAll('_',' ')}</span><h2 style="font-size:${['sentence','blank'].includes(s.testMode)?'23':'32'}px">${esc(prompt)}</h2>${s.testMode==='listening'?`<button class="btn secondary" data-speak="${w.id}">${icon('sound')} Play pronunciation</button>`:''}${s.testMode==='choice'?s.options.map(v=>`<button class="option ${s.answer===v?'selected':''}" data-option="${esc(v)}" ${s.checked?'disabled':''}>${esc(v)}</button>`).join(''):`<form id="test-form" style="width:100%"><input id="answer" class="recall-input" autocomplete="off" aria-label="Your answer" placeholder="Type the English word…" value="${esc(s.answer)}" ${s.checked?'disabled':''}><br>${s.checked?'':'<button class="btn" type="submit">Check answer</button>'}</form>`}${s.checked?`<div class="feedback ${s.correct?'':'wrong'}">${s.correct?'Correct. Well done.':`The correct answer is <strong>${esc(s.testMode==='choice'?w.uz:w.en)}</strong>.`}<br>${esc(w.example)}</div><button class="btn" id="next-test">${s.index===s.list.length-1?'See results':'Next question'} ${icon('arrow')}</button>`:''}</section></div>`}
function shuffled(a){return a.map(v=>({v,r:Math.random()})).sort((a,b)=>a.r-b.r).map(o=>o.v)}
function makeOptions(){if(session?.kind==='test'&&session.list[session.index]){const w=session.list[session.index];session.options=shuffled([w.uz,...shuffled(words.filter(x=>x.id!==w.id)).slice(0,3).map(x=>x.uz)])}}
function startTest(mode){session={kind:'test',testMode:mode,list:shuffled(words).slice(0,6),index:0,score:0,answer:'',checked:false};makeOptions();render()}
function checkTest(value){if(session.checked)return;if(!value.trim())return toast('Type an answer first.');const s=session,w=s.list[s.index];s.answer=value;s.checked=true;s.correct=norm(value)===norm(s.testMode==='choice'?w.uz:w.en);if(s.correct)s.score++;record(w,s.correct?'known':'unknown');render()}
function statistics(){const all=Object.values(state.activity),answers=all.reduce((a,b)=>a+b.answers,0),correct=all.reduce((a,b)=>a+b.correct,0);return `${heading('YOUR LEARNING JOURNEY','Progress you can build on.','A useful measure of learning is what you remember, consistently.')}<div class="stats" style="margin-bottom:23px">${stat('Words studied',learned(),`${mastered()} words on 7+ day intervals`,'book')}${stat('Recall accuracy',answers?Math.round(correct/answers*100)+'%':'—',`${answers} recorded answers`,'target')}${stat('Active days',all.length,`${streak()} day current streak`,'calendar')}</div><div class="dashboard-grid"><div class="left-col"><section class="card"><div class="card-head"><h2>Progress by unit</h2></div>${units.map((u,i)=>{let n=words.filter(w=>w.unit===i&&rec(w.id)).length;return `<div style="margin:24px 0"><div class="study-toolbar"><strong style="font-size:12px">${u}</strong><span class="muted" style="font-size:11px">${n} / ${words.filter(w=>w.unit===i).length} practice words</span></div><div class="bar"><i style="width:${words.filter(w=>w.unit===i).length?n/words.filter(w=>w.unit===i).length*100:0}%"></i></div></div>`}).join('')}</section><section class="card"><div class="card-head"><h2>Review schedule</h2></div>${[['Ready now',due().length],['Within the next day',Object.values(state.records).filter(r=>r.due>now()&&r.due<=now()+86400000).length],['Later',Object.values(state.records).filter(r=>r.due>now()+86400000).length]].map(([t,n])=>`<div class="ranking"><span class="person">${t}</span><strong>${n} words</strong></div>`).join('')}</section></div><aside class="right-col">${activity()}<section class="card"><div class="card-head"><h2>Quiet milestones</h2></div>${[['First step','Study your first word',learned()>0],['Daily commitment','Reach today’s learning goal',today().ids.length>=state.goal],['A lasting habit','Study on 7 consecutive days',streak()>=7],['Building confidence','Retain 10 words for at least 7 days',mastered()>=10]].map(([t,d,on])=>`<div class="achievement" style="opacity:${on?1:.45}"><span class="icon-box">${icon(on?'check':'target')}</span><div><strong>${t}</strong><p>${d}</p></div></div>`).join('')}</section></aside></div>`}
function leaderboard(){return `${heading('CONSISTENT EFFORT ADDS UP','A little friendly perspective.','Learning comes first. XP is a small reflection of the work you put in.')}<div class="stats" style="margin-bottom:23px">${stat('Weekly XP',weekXP(),'Your last 7 days','chart')}${stat('Lifetime XP',state.xp,'Your cumulative study effort','trophy')}${stat('Current level',Math.floor(state.xp/500)+1,`${500-state.xp%500} XP to the next level`,'target')}</div><div class="section-grid" style="grid-template-columns:repeat(auto-fit,minmax(260px,1fr))">${['Weekly TOP 10','Global TOP 10'].map((t,i)=>`<section class="card"><div class="card-head"><h2>${t}</h2>${icon('trophy')}</div><div class="ranking"><span class="rank">—</span><span class="avatar">YS</span><span class="person"><strong>You</strong><small>Not ranked · Local progress</small></span><span class="xp">${i?state.xp:weekXP()} XP</span></div><div class="empty" style="font-size:12px;line-height:1.9">A shared community hasn’t been connected yet.<br>Global rankings require accounts and a shared database.</div><div class="leader-note">No simulated learners or rankings. Your personal XP is saved on this device.</div></section>`).join('')}</div>`}
function settings(){return `${heading('STUDY PREFERENCES','Make a little room for learning.','Choose a sustainable goal you can return to every day.')}<div class="study-wrap"><section class="card"><div class="card-head"><h2>Your daily learning goal</h2></div><p class="muted">Count distinct words practised, including new vocabulary and reviews.</p><form id="goal-form" class="goal-row"><input id="goal" type="number" min="1" max="36" value="${state.goal}" aria-label="Daily word goal" required><span class="muted">words per day</span><button class="btn" type="submit">Save goal</button></form></section><section class="card" style="margin-top:20px"><h2 style="font-size:14px">Your learning data</h2><p class="muted" style="font-size:12px;line-height:1.9">Progress is stored in this browser. Export a backup to keep a copy. This version includes all 100 textbook units and ${words.length} original interactive starter words. Textbook vocabulary has not yet been fully converted into translated flashcards.</p><button class="btn secondary" id="export">Export progress ${icon('arrow')}</button><label class="btn secondary" style="cursor:pointer;margin-left:8px">Import backup<input id="import" type="file" accept="application/json" hidden></label></section></div>`}
function bind(){bindBook();document.querySelectorAll('[data-speak]').forEach(b=>b.onclick=()=>speak(+b.dataset.speak));document.querySelectorAll('[data-start]').forEach(b=>b.onclick=()=>start(b.dataset.start));document.querySelectorAll('[data-unit]').forEach(b=>b.onclick=()=>start('unit',+b.dataset.unit));document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));document.querySelectorAll('[data-board]').forEach(b=>b.onclick=()=>{board=b.dataset.board;render()});document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{session.mode=b.dataset.mode;session.checked=false;session.answer='';session.flipped=false;render()});document.querySelectorAll('[data-rate]').forEach(b=>b.onclick=()=>{record(session.list[session.index],b.dataset.rate);session.done++;advance()});document.querySelectorAll('[data-test]').forEach(b=>b.onclick=()=>startTest(b.dataset.test));document.querySelectorAll('[data-option]').forEach(b=>b.onclick=()=>checkTest(b.dataset.option));const on=(id,fn)=>{const e=document.getElementById(id);if(e)e.onclick=fn};on('reveal',()=>{session.flipped=true;render()});on('next-recall',advance);on('next-test',()=>{session.index++;session.checked=false;session.answer='';makeOptions();if(session.index===session.list.length){state.testResults.push({date:now(),score:session.score,total:session.list.length,mode:session.testMode});save()}render()});for(const [id,fn]of[['recall-form',checkRecall],['test-form',()=>checkTest(document.getElementById('answer').value)],['goal-form',()=>{const value=+document.getElementById('goal').value;if(!Number.isInteger(value)||value<1||value>36)return;state.goal=value;save();toast('Daily goal updated.');render()}]]){const f=document.getElementById(id);if(f)f.onsubmit=e=>{e.preventDefault();fn()}}const sel=document.getElementById('unit-filter');if(sel)sel.onchange=()=>{filter=+sel.value;render()};const q=document.getElementById('search');if(q)q.oninput=()=>{const pos=q.selectionStart;search=q.value;render();const nq=document.getElementById('search');nq.focus();nq.setSelectionRange(pos,pos)};on('export',()=>{const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`wordly-progress-${dayKey()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)});const im=document.getElementById('import');if(im)im.onchange=async()=>{try{const v=JSON.parse(await im.files[0].text());if(!validBackup(v))throw Error();state=v;save();render();toast('Progress restored.')}catch{toast('Please select a valid WORDLY progress backup.')}};}
function validBackup(v){return v&&Number.isInteger(v.goal)&&v.goal>=1&&v.goal<=36&&Number.isFinite(v.xp)&&v.xp>=0&&v.records&&typeof v.records==='object'&&Object.entries(v.records).every(([id,r])=>words[+id]&&['known','difficult','unknown'].includes(r.status)&&['interval','ease','reviews','lapses','due','last'].every(k=>Number.isFinite(r[k])&&r[k]>=0))&&v.activity&&Object.values(v.activity).every(a=>Array.isArray(a.ids)&&a.ids.every(id=>Number.isInteger(id)&&words[id])&&Number.isFinite(a.answers)&&Number.isFinite(a.correct))&&v.weekly&&Object.values(v.weekly).every(n=>Number.isFinite(n)&&n>=0)&&Array.isArray(v.testResults)}
document.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA','SELECT','BUTTON'].includes(document.activeElement?.tagName)||!session||!['review','flashcards'].includes(page)||!session.list[session.index]||session.mode!=='flash')return;if(e.code==='Space'){e.preventDefault();session.flipped=true;render()}if(session.flipped&&['1','2','3'].includes(e.key)){e.preventDefault();record(session.list[session.index],{'1':'unknown','2':'difficult','3':'known'}[e.key]);session.done++;advance()}if(e.key==='ArrowLeft'&&session.index>0){e.preventDefault();session.index--;session.flipped=false;render()}});
render();
